import sqlite3
import sys
import requests
from urllib.parse import urlparse

def create_db():
    conn = sqlite3.connect('links.db')
    c = conn.cursor()
    c.execute('''CREATE TABLE IF NOT EXISTS links
                 (id INTEGER PRIMARY KEY AUTOINCREMENT,
                  url TEXT UNIQUE,
                  status INTEGER)''')
    conn.commit()
    conn.close()

def fetch_url_status(url):
    try:
        response = requests.get(url, timeout=5)
        return response.status_code
    except requests.RequestException:
        return None

def process_file(path):
    try:
        with open(path, 'r') as f:
            urls = [line.strip() for line in f if line.strip()]
    except FileNotFoundError:
        print('file not found', file=sys.stderr)
        sys.exit(1)
    except IOError:
        print('file not found', file=sys.stderr)
        sys.exit(1)

    conn = sqlite3.connect('links.db')
    c = conn.cursor()

    for url in urls:
        if not url:
            continue
        parsed = urlparse(url)
        if not parsed.scheme or not parsed.netloc:
            print(f'Invalid URL: {url}', file=sys.stderr)
            continue

        status = fetch_url_status(url)
        if status is not None:
            c.execute('INSERT INTO links (url, status) VALUES (?, ?)', (url, status))

    conn.commit()
    conn.close()

def filter_query(conn, filter_col, filter_val):
    c = conn.cursor()
    if filter_col == 'id':
        c.execute('SELECT id, url, status FROM links WHERE id = ?', (int(filter_val),))
    elif filter_col == 'url':
        c.execute('SELECT id, url, status FROM links WHERE url = ?', (filter_val,))
    elif filter_col == 'status':
        c.execute('SELECT id, url, status FROM links WHERE status = ?', (int(filter_val),))
    else:
        c.execute('SELECT id, url, status FROM links')
    return c.fetchall()

def main():
    create_db()
    path = sys.argv[1]
    process_file(path)

    conn = sqlite3.connect('links.db')
    c = conn.cursor()

    filter_col = None
    filter_val = None
    for arg in sys.argv[2:]:
        if arg.startswith('--filter'):
            parts = arg.split('=', 1)
            if len(parts) != 2:
                print(f'Invalid filter argument: {arg}', file=sys.stderr)
                sys.exit(1)
            filter_col, filter_val = parts
            if filter_col not in ['id', 'url', 'status']:
                print(f'Invalid filter column: {filter_col}', file=sys.stderr)
                sys.exit(1)

    rows = filter_query(conn, filter_col, filter_val) if filter_col else c.execute('SELECT id, url, status FROM links ORDER BY id')

    for row in rows:
        print('\t'.join(map(str, row)))

    conn.close()

if __name__ == '__main__':
    main()
